package ApanaCollegePattern2;

public class SquarePatternWithAlpha {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int n=5;
	
		for(int i=1;i<=n;i++)
		{
			char ch='A';
			for(int j=1;j<=n;j++)
			{
				System.out.print(ch+" " );
				ch++;
				
				}
			System.out.println();	
			
		}

	}

}
